// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title WaterQuality
 * @dev Data integrity layer for AQUA-ETHIC water quality monitoring
 * @notice Anchors hashes of water quality records to blockchain for tamper-proof verification
 */
contract WaterQuality {
    // ========================================
    // STATE VARIABLES
    // ========================================
    
    address public owner;
    
    struct Record {
        string sensorId;
        string sourceType;
        bytes32 dataHash;
        uint256 timestamp;
    }
    
    // Mapping from sensorId to Record
    mapping(string => Record) public records;
    
    // Track all sensor IDs
    string[] public sensorIds;
    
    // Check if sensor exists
    mapping(string => bool) public sensorExists;
    
    // ========================================
    // EVENTS
    // ========================================
    
    event DataAnchored(
        string indexed sensorId, 
        bytes32 dataHash, 
        uint256 timestamp,
        string sourceType
    );
    
    event OwnershipTransferred(
        address indexed previousOwner,
        address indexed newOwner
    );
    
    // ========================================
    // MODIFIERS
    // ========================================
    
    modifier onlyOwner() {
        require(msg.sender == owner, "Not authorized to anchor data");
        _;
    }
    
    modifier sensorNotExists(string memory _sensorId) {
        require(!sensorExists[_sensorId], "Sensor ID already anchored");
        _;
    }
    
    modifier sensorExistsCheck(string memory _sensorId) {
        require(sensorExists[_sensorId], "Sensor ID does not exist");
        _;
    }
    
    // ========================================
    // CONSTRUCTOR
    // ========================================
    
    constructor() {
        owner = msg.sender;
    }
    
    // ========================================
    // CORE FUNCTIONS
    // ========================================
    
    /**
     * @dev Anchor a record hash to the blockchain
     * @param _sensorId Unique identifier for the sensor/record
     * @param _sourceType Source of the data ("REMOTE_SENSING" or "IOT")
     * @param _dataHash SHA-256 hash of the record data
     */
    function recordData(
        string memory _sensorId,
        string memory _sourceType,
        bytes32 _dataHash
    ) 
        public 
        onlyOwner 
        sensorNotExists(_sensorId) 
    {
        // Validate source type
        require(
            keccak256(abi.encodePacked(_sourceType)) == keccak256(abi.encodePacked("REMOTE_SENSING")) ||
            keccak256(abi.encodePacked(_sourceType)) == keccak256(abi.encodePacked("IOT")),
            "Invalid source type"
        );
        
        // Store the record
        records[_sensorId] = Record({
            sensorId: _sensorId,
            sourceType: _sourceType,
            dataHash: _dataHash,
            timestamp: block.timestamp
        });
        
        sensorExists[_sensorId] = true;
        sensorIds.push(_sensorId);
        
        // Emit event
        emit DataAnchored(_sensorId, _dataHash, block.timestamp, _sourceType);
    }
    
    /**
     * @dev Verify if a record's hash matches the anchored hash
     * @param _sensorId Unique identifier for the sensor
     * @param _currentHash Current SHA-256 hash to verify
     * @return bool True if hashes match
     */
    function verifyRecord(
        string memory _sensorId,
        bytes32 _currentHash
    ) 
        public 
        view 
        sensorExistsCheck(_sensorId) 
        returns (bool) 
    {
        return records[_sensorId].dataHash == _currentHash;
    }
    
    /**
     * @dev Get a record by sensor ID
     * @param _sensorId Unique identifier for the sensor
     * @return Record struct
     */
    function getRecord(string memory _sensorId) 
        public 
        view 
        sensorExistsCheck(_sensorId) 
        returns (Record memory) 
    {
        return records[_sensorId];
    }
    
    /**
     * @dev Get all sensor IDs
     * @return string[] Array of all sensor IDs
     */
    function getAllSensorIds() 
        public 
        view 
        returns (string[] memory) 
    {
        return sensorIds;
    }
    
    /**
     * @dev Get total number of anchored records
     * @return uint256 Count of records
     */
    function getRecordCount() 
        public 
        view 
        returns (uint256) 
    {
        return sensorIds.length;
    }
    
    /**
     * @dev Transfer ownership to a new address
     * @param _newOwner Address of the new owner
     */
    function transferOwnership(address _newOwner) 
        public 
        onlyOwner 
    {
        require(_newOwner != address(0), "New owner is zero address");
        address oldOwner = owner;
        owner = _newOwner;
        emit OwnershipTransferred(oldOwner, _newOwner);
    }
}

